/* HHA chapters 9, 10, 11 — observed hands-on skills: hygiene, transfers, range of motion. Format: see hha-a.js */
(window.HHA = window.HHA || []).push(
{ch:9, cfr:"(b)(3)(ix)", observed:true,
 title:["Ijyèn pèsonèl ak abiman","Personal hygiene and grooming"],
 src:["S6","S12","S1"],
 sections:[
  {h:["Sa règ la mande","What the rule requires"],src:["S6","S12"],b:[
   ["p","Règ federal la mande pou enfimyè a gade w fè swen ijyèn yo ak yon kliyan oswa yon moun k ap jwe wòl kliyan: beny nan kabann, beny an chita (sponge), nan basen oswa douch, chanpou nan lavabo, basen oswa kabann, swen zong ak po, swen bouch, ak ede kliyan an ale nan twalèt.","The federal rule requires the nurse to watch you do hygiene care with a client or a person playing the client: bed bath, sponge, tub or shower bath, shampoo in the sink, tub or bed, nail and skin care, oral hygiene, and toileting and elimination."]]},
  {h:["Règ pou chak swen","Rules for every care task"],src:["S1"],b:[
   ["n","Lave men w, prezante w, epi eksplike sa w pral fè.","Clean your hands, introduce yourself, and explain what you will do."],
   ["n","Bay prive: fèmen pòt ak rido, epi kouvri pati kò ou pa p lave.","Give privacy: close doors and curtains, and keep covered the parts you are not washing."],
   ["n","Kite kliyan an fè sa l kapab poukont li, epi kite l chwazi (rad, lè, pwodui).","Let the client do what they can, and let them choose (clothes, timing, products)."],
   ["n","Teste dlo a anvan l touche kliyan an.","Test the water before it touches the client."],
   ["n","Mete gan si w ka touche likid kò oswa po ki blese.","Wear gloves if you may touch body fluids or broken skin."],
   ["n","Gade po a pandan w ap lave l, epi rapòte wouj, blesi oswa chanjman.","Look at the skin while you wash, and report redness, sores or changes."]]},
  {h:["Beny nan kabann","Bed bath"],src:["S1"],b:[
   ["li","Lave depi zòn ki pi pwòp yo rive nan zòn ki pi sal yo: figi, bra, pwatrin, vant, janm, do, epi zòn pèsonèl la nan fen.","Wash from cleanest to dirtiest: face, arms, chest, abdomen, legs, back, then the perineal area last."],
   ["li","Je yo: dlo sèlman, san savon, depi kwen anndan an rive kwen deyò a, yon pati diferan nan twal la pou chak je.","Eyes: water only, no soap, from the inner corner to the outer corner, a different part of the washcloth for each eye."],
   ["li","Chanje dlo a lè l vin frèt, gen savon oswa sal, ak anvan swen zòn pèsonèl la.","Change the water when it gets cool, soapy or dirty, and before perineal care."],
   ["li","Seche byen, sitou ant zòtèy yo ak anba pli po yo.","Dry well, especially between the toes and under skin folds."]]},
  {h:["Beny an chita, nan basen oswa douch","Sponge, tub or shower bath"],src:["S1"],b:[
   ["li","Sèvi ak yon chèz douch, yon tapi ki pa glise ak ba pou kenbe si plan swen an mande yo.","Use a shower chair, non-slip mat and grab bars if the care plan calls for them."],
   ["li","Pa janm kite kliyan an poukont li nan basen an oswa douch la si sa pa an sekirite pou li.","Never leave the client alone in the tub or shower if that is not safe for them."],
   ["li","Rapòte toudi oswa feblès; fè l chita touswit.","Report dizziness or weakness, and have them sit down right away."]]},
  {h:["Chanpou","Shampoo"],src:["S1"],b:[
   ["li","Nan kabann: sèvi ak yon basen chanpou oswa yon plastik pou dlo a koule nan yon bokit, epi pwoteje dra yo.","In bed: use a shampoo tray or plastic sheet so water drains into a basin, and protect the linens."],
   ["li","Kouvri je kliyan an ak yon ti sèvyèt, epi seche cheve a vit pou l pa frèt.","Cover the client's eyes with a small towel, and dry the hair promptly so they do not get chilled."],
   ["li","Respekte kijan kliyan an konn okipe cheve l ak pwodui li konn sèvi.","Respect how the client usually cares for their hair and the products they use."]]},
  {h:["Zong ak po","Nails and skin"],src:["S1","S12"],b:[
   ["li","Tranpe men yo nan dlo tyèd, netwaye anba zong yo, epi lime yo.","Soak the hands in warm water, clean under the nails, and file them."],
   ["li","Pa koupe zong yon kliyan ki gen dyabèt oswa move sikilasyon. Rapòte bay enfimyè a.","Do not cut the nails of a client with diabetes or poor circulation. Report to the nurse."],
   ["li","Pa koupe zong pye si plan swen an pa mande l epi w pa fòme pou sa.","Do not cut toenails unless the care plan calls for it and you are trained."],
   ["li","Mete krèm sou po sèk ki pa blese, men pa ant zòtèy yo.","Apply lotion to dry, unbroken skin, but not between the toes."]]},
  {h:["Bouch ak dan atifisyèl","Mouth and dentures"],src:["S1"],b:[
   ["li","Bwose dan ak lang, omwen de fwa pa jou, oswa jan plan swen an di.","Brush the teeth and tongue at least twice a day, or as the care plan says."],
   ["li","Pou yon kliyan ki pa reponn: vire tèt li sou kote, sèvi ak ti kantite likid sèlman, epi pa janm mete dwèt ou nan bouch li.","For an unresponsive client: turn the head to the side, use only a small amount of liquid, and never put your fingers in their mouth."],
   ["li","Manyen dan atifisyèl sou yon sèvyèt oswa yon basen ak dlo pou yo pa kase si yo tonbe. Rense yo ak dlo frèt oswa tyèd, pa cho.","Handle dentures over a towel or a basin of water so they do not break if dropped. Rinse with cool or lukewarm water, not hot."],
   ["li","Sere yo nan yon bwat ki gen non kliyan an, ak dlo oswa likid tranpe.","Store them in a container labeled with the client's name, in water or soaking solution."]]},
  {h:["Twalèt ak zòn pèsonèl","Toileting and perineal care"],src:["S1"],b:[
   ["li","Ede kliyan an ale nan twalèt, sèvi ak yon chèz twalèt (commode), yon basen kabann (bedpan) oswa yon pistolè (urinal), selon plan swen an.","Help the client use the toilet, a commode, a bedpan or a urinal, as the care plan says."],
   ["li","Swen zòn pèsonèl: toujou depi devan rive dèyè, ak yon pati pwòp nan twal la chak fwa.","Perineal care: always from front to back, with a clean part of the washcloth each stroke."],
   ["li","Sak kateter: toujou pi ba pase vesi a, tib la pa pliye, epi sak la pa touche atè.","Catheter bag: always below the bladder, tubing not kinked, and the bag off the floor."],
   ["li","Rapòte pipi oswa poupou ki pa nòmal: koulè, sant, san, oswa kliyan an pa pipi.","Report abnormal urine or stool: color, odor, blood, or the client not urinating."]]},
  {h:["Abiye","Dressing"],src:["S1","S29"],b:[
   ["li","Kite kliyan an chwazi rad li, epi kite l fè sa l kapab poukont li.","Let the client choose their clothes, and let them do what they can themselves."],
   ["li","Si yon bò kò a fèb: abiye bò ki fèb la an premye. Pou dezabiye, retire rad la sou bò ki fò a an premye.","If one side is weak: dress the weak (affected) side first. To undress, take clothing off the strong side first."]]}],
 terms:[["bed bath","beny nan kabann"],["perineal care","swen zòn pèsonèl"],["dentures","dan atifisyèl"],["commode","chèz twalèt"],["bedpan","basen kabann"],["urinal","pistolè"],["catheter","kateter"],["oral hygiene","ijyèn bouch"]],
 skills:[
  {title:["Beny nan kabann","Bed bath"],steps:[
   ["Lave men w, eksplike, bay prive, epi ranmase sa w bezwen.","Clean your hands, explain, give privacy, and gather supplies."],
   ["Teste dlo a. Kouvri kliyan an ak yon dra beny, epi dekouvri sèlman pati w ap lave a.","Test the water. Cover the client with a bath blanket and uncover only the part you are washing."],
   ["Je yo an premye: dlo sèlman, depi anndan rive deyò, yon pati diferan nan twal la pou chak je.","Eyes first: water only, inner to outer corner, a different part of the cloth for each eye."],
   ["Figi, kou, bra, pwatrin, vant, janm, pye. Rense epi seche chak pati.","Face, neck, arms, chest, abdomen, legs, feet. Rinse and dry each part."],
   ["Chanje dlo a. Vire kliyan an sou kote pou do a.","Change the water. Turn the client to the side for the back."],
   ["Mete gan pou zòn pèsonèl la, depi devan rive dèyè.","Wear gloves for perineal care, front to back."],
   ["Abiye kliyan an, ranje kabann nan, epi lave men w. Rapòte chanjman sou po a.","Dress the client, tidy the bed, and clean your hands. Report skin changes."]],
   note:["Chanje dlo a chak fwa l vin frèt, gen savon oswa sal.","Change the water whenever it gets cool, soapy or dirty."]},
  {title:["Ede ak douch oswa basen","Tub or shower assist"],steps:[
   ["Tcheke plan swen an pou ekipman: chèz douch, tapi, ba pou kenbe.","Check the care plan for equipment: shower chair, mat, grab bars."],
   ["Teste dlo a anvan kliyan an antre.","Test the water before the client gets in."],
   ["Ede l antre tou dousman; fè l chita sou chèz la si plan an mande l.","Help them in slowly; have them sit on the chair if the plan calls for it."],
   ["Kite l lave sa l kapab; ede ak rès la.","Let them wash what they can; help with the rest."],
   ["Ede l soti, seche l byen, epi mete l chita pou l abiye.","Help them out, dry well, and seat them to dress."]],
   note:["Pa janm kite yon kliyan ki pa an sekirite poukont li nan basen oswa douch la.","Never leave a client who is not safe alone in the tub or shower."]},
  {title:["Chanpou nan kabann","Shampoo in bed"],steps:[
   ["Mete yon plastik oswa yon basen chanpou anba tèt kliyan an, ak yon bokit pou dlo a.","Place a plastic sheet or shampoo tray under the head, with a basin for the water."],
   ["Kouvri je l ak yon ti sèvyèt.","Cover the eyes with a small towel."],
   ["Mouye cheve a ak dlo tyèd ou fin teste, mete chanpou, masaj po tèt la.","Wet the hair with tested warm water, apply shampoo, massage the scalp."],
   ["Rense nèt, epi seche cheve a vit.","Rinse well, and dry the hair promptly."],
   ["Penyen l jan kliyan an renmen, epi chanje dra ki mouye.","Comb it the way the client likes, and change any wet linens."]],
   note:["Respekte pwodui ak abitid kliyan an pou cheve l.","Respect the client's hair products and habits."]},
  {title:["Swen zong men","Fingernail care"],steps:[
   ["Tcheke plan swen an. Si kliyan an gen dyabèt oswa move sikilasyon, pa koupe zong yo.","Check the care plan. If the client has diabetes or poor circulation, do not cut the nails."],
   ["Tranpe men yo nan dlo tyèd kèk minit.","Soak the hands in warm water for a few minutes."],
   ["Netwaye anba zong yo ak yon bwa oswa zouti apwopriye.","Clean under the nails with an orange stick or proper tool."],
   ["Lime zong yo pou yo lis.","File the nails smooth."],
   ["Mete krèm sou men yo, epi rapòte nenpòt blesi.","Apply lotion to the hands, and report any sores."]],
   note:["Zong pye: sèlman si plan swen an mande l epi w fòme pou sa.","Toenails: only if the care plan calls for it and you are trained."]},
  {title:["Swen bouch ak dan atifisyèl","Mouth and denture care"],steps:[
   ["Lave men w, mete gan, epi fè kliyan an chita dwat.","Clean your hands, put on gloves, and sit the client upright."],
   ["Bwose dan ak lang tou dousman, epi kite l rense.","Brush the teeth and tongue gently, and let them rinse."],
   ["Dan atifisyèl: retire yo, epi bwose yo sou yon sèvyèt oswa yon basen dlo.","Dentures: remove them, and brush them over a towel or a basin of water."],
   ["Rense yo ak dlo frèt oswa tyèd, pa cho.","Rinse with cool or lukewarm water, not hot."],
   ["Remete yo oswa sere yo nan yon bwat ki gen non kliyan an, ak dlo.","Put them back or store them in a labeled container with water."]],
   note:["Rapòte senyen, blesi nan bouch oswa dan ki pa byen chita.","Report bleeding, mouth sores or loose-fitting dentures."]},
  {title:["Basen kabann ak twalèt","Bedpan and toileting"],steps:[
   ["Bay prive epi mete gan.","Give privacy and put on gloves."],
   ["Fè kliyan an vire sou kote, mete basen an anba l, epi vire l tounen sou do.","Turn the client to the side, place the bedpan, and roll them back onto it."],
   ["Leve tèt kabann nan si sa pèmèt, epi kite papye twalèt ak sonèt nan rive men l.","Raise the head of the bed if allowed, and leave toilet paper and a call bell within reach."],
   ["Retire basen an, netwaye depi devan rive dèyè, epi ede l lave men l.","Remove the bedpan, clean front to back, and help them clean their hands."],
   ["Gade sa ki ladan l, vide l, netwaye basen an, epi rapòte sa ki pa nòmal.","Observe the contents, empty and clean the bedpan, and report anything abnormal."]],
   note:["Ekri pipi oswa poupou si plan swen an mande w mezire yo.","Record output if the care plan asks you to measure it."]},
  {title:["Swen zòn pèsonèl","Perineal care"],steps:[
   ["Bay prive, eksplike, epi mete gan.","Give privacy, explain, and put on gloves."],
   ["Teste dlo a epi kouvri kliyan an, dekouvri sèlman zòn nan.","Test the water and keep the client covered except the area."],
   ["Lave depi devan rive dèyè, ak yon pati pwòp nan twal la chak fwa.","Wash front to back, with a clean part of the cloth each stroke."],
   ["Rense epi seche byen.","Rinse and dry well."],
   ["Retire gan yo, lave men w, epi rapòte wouj, likid oswa sant ki pa nòmal.","Remove gloves, clean your hands, and report redness, discharge or unusual odor."]],
   note:["Depi devan rive dèyè anpeche mikwòb poupou antre nan pipi.","Front to back keeps stool germs away from the urinary tract."]}],
 qs:[
  ["h901",0,["bed bath","beny nan kabann"],
   ["Pandan yon beny nan kabann, kijan pou w lave je kliyan an?","Ak dlo sèlman, depi kwen anndan rive kwen deyò","Ak savon, depi deyò rive anndan","Ak alkòl","Ak menm pati nan twal la pou de je yo","Pa mete savon nan je. Lave depi anndan rive deyò, ak yon pati diferan nan twal la pou chak je, pou w pa pote mikwòb."],
   ["During a bed bath, how should you wash the client's eyes?","With water only, from the inner corner to the outer corner","With soap, from outer to inner","With alcohol","With the same part of the cloth for both eyes","No soap in the eyes. Wash inner to outer, with a different part of the cloth for each eye, so you do not spread germs."]],
  ["h902",2,["perineal care","swen zòn pèsonèl"],
   ["Nan ki direksyon pou w netwaye zòn pèsonèl yon fanm?","Depi dèyè rive devan","Nan wonn","Depi devan rive dèyè","Nenpòt direksyon","Depi devan rive dèyè anpeche mikwòb poupou antre nan pipi epi lakòz enfeksyon."],
   ["In which direction do you clean a woman's perineal area?","Back to front","In circles","Front to back","Any direction","Front to back keeps stool germs out of the urinary tract and prevents infection."]],
  ["h903",1,["nail care","swen zong"],
   ["Kliyan an gen dyabèt epi zong li long. Kisa ou fè?","Koupe yo kout","Pa koupe yo; rapòte bay enfimyè a","Mande fanmi an koupe yo","Rache po bò zong yo","Yon ti blesi ka grav pou moun ki gen dyabèt oswa move sikilasyon. Pa koupe zong yo: rapòte bay enfimyè a."],
   ["A client with diabetes has long nails. What do you do?","Cut them short","Do not cut them; report to the nurse","Ask the family to cut them","Trim the cuticles","A small cut can be serious for people with diabetes or poor circulation. Do not cut the nails: report to the nurse."]],
  ["h904",3,["dentures","dan atifisyèl"],
   ["Kijan pou w netwaye dan atifisyèl yon kliyan?","Ak dlo bouyi","Kenbe yo anlè nan lè a","Mete yo nan yon napkin papye","Sou yon sèvyèt oswa yon basen dlo, ak dlo frèt oswa tyèd","Manyen dan atifisyèl sou yon sèvyèt oswa yon basen dlo pou yo pa kase si yo tonbe. Dlo cho ka defòme yo."],
   ["How should you clean a client's dentures?","In boiling water","Holding them up in the air","Wrapped in a paper napkin","Over a towel or basin of water, with cool or lukewarm water","Handle dentures over a towel or basin of water so they do not break if dropped. Hot water can warp them."]],
  ["h905",0,["catheter bag","sak kateter"],
   ["Ki kote sak kateter kliyan an dwe ye?","Pi ba pase vesi a, epi pa atè","Sou vant kliyan an","Pandye sou ba kabann nan pi wo pase kliyan an","Atè bò kabann nan","Sak la rete pi ba pase vesi a pou pipi pa retounen andedan, epi pa atè pou l rete pwòp."],
   ["Where should the client's catheter bag be?","Below the bladder and off the floor","On the client's abdomen","Hung above the client on the bed rail","On the floor by the bed","Keep the bag below the bladder so urine does not flow back, and off the floor to keep it clean."]],
  ["h906",1,["bath water","dlo beny"],
   ["Pandan yon beny nan kabann, kilè pou w chanje dlo a?","Sèlman nan fen beny lan","Lè l vin frèt, gen savon oswa sal, ak anvan swen zòn pèsonèl la","Pa janm","Sèlman si kliyan an mande l","Dlo frèt fè kliyan an frèt, epi dlo sal pote mikwòb. Chanje l lè l vin frèt, gen savon oswa sal."],
   ["During a bed bath, when do you change the water?","Only at the end of the bath","When it gets cool, soapy or dirty, and before perineal care","Never","Only if the client asks","Cool water chills the client, and dirty water carries germs. Change it when it gets cool, soapy or dirty."]],
  ["h907", 1, ["dizziness", "toudi"], ["Pandan douch la, kliyan w lan di li toudi epi li santi l fèb. Kisa ou fè an premye?", "Fini vit pou l ka al kouche", "Fè l chita touswit, epi rapòte sa", "Kite l pou w al chèche yon vè dlo", "Mete dlo a pi cho pou l chofe", "Toudi nan douch ka fè moun tonbe. Fè l chita touswit, sou chèz douch la si genyen youn, rete avè l, epi rapòte sa."], ["During a shower, your client says they feel dizzy and weak. What do you do first?", "Finish quickly so they can lie down", "Have them sit down right away, then report it", "Leave them to get a glass of water", "Make the water hotter to warm them up", "Dizziness in the shower can lead to a fall. Have them sit down right away, on the shower chair if there is one, stay with them, and report it."]],
  ["h908",3,["oral care","swen bouch"],
   ["W ap fè swen bouch yon kliyan ki pa reponn. Kisa ki enpòtan?","Vide yon vè dlo nan bouch li","Mete dwèt ou nan bouch li pou netwaye","Leve tèt li dwat dèyè","Vire tèt li sou kote epi sèvi ak ti kantite likid sèlman","Yon kliyan ki pa reponn ka toufe. Vire tèt li sou kote, sèvi ak ti kantite likid, epi pa janm mete dwèt ou nan bouch li."],
   ["You are giving mouth care to an unresponsive client. What matters most?","Pour a glass of water into the mouth","Put your fingers in the mouth to clean","Tilt the head straight back","Turn the head to the side and use only a small amount of liquid","An unresponsive client can choke. Turn the head to the side, use little liquid, and never put your fingers in their mouth."]],
  ["h909", 3, ["bed bath order", "lòd beny nan kabann"], ["Pandan yon beny nan kabann, ki zòn ou lave an dènye?", "Figi a", "Bra yo", "Janm yo", "Zòn pèsonèl la", "Lave depi zòn ki pi pwòp yo rive nan zòn ki pi sal yo: figi, bra, pwatrin, vant, janm, do, epi zòn pèsonèl la nan fen."], ["During a bed bath, which area do you wash last?", "The face", "The arms", "The legs", "The perineal area", "Wash from cleanest to dirtiest: face, arms, chest, abdomen, legs, back, then the perineal area last."]],
  ["h910", 0, ["dry thoroughly", "seche byen"], ["Apre w fin lave pye kliyan an, kisa ki enpòtan?", "Seche byen, sitou ant zòtèy yo", "Kite yo mouye pou po a rete mou", "Mete krèm ant zòtèy yo", "Mete chosèt touswit pandan yo mouye", "Seche byen, sitou ant zòtèy yo ak anba pli po yo."], ["After washing the client's feet, what is important?", "Dry them well, especially between the toes", "Leave them damp so the skin stays soft", "Put lotion between the toes", "Put socks on right away while they are wet", "Dry well, especially between the toes and under skin folds."]],
  ["h911", 1, ["bath safety", "sekirite nan beny"], ["Kliyan w lan pa fèm sou pye l epi li chita nan basen an. Telefòn sonnen nan lòt chanm nan. Kisa ou fè?", "Al reponn li vit", "Rete ak kliyan an; pa kite l poukont li nan basen an", "Mande kliyan an kenbe ba a pandan w ale", "Kite plis dlo koule pou l okipe", "Pa janm kite kliyan an poukont li nan basen an oswa douch la si sa pa an sekirite pou li."], ["Your client is unsteady and sitting in the tub. The phone rings in another room. What do you do?", "Go answer it quickly", "Stay with the client; do not leave them alone in the tub", "Ask the client to hold the grab bar while you go", "Let more water run to keep them busy", "Never leave the client alone in the tub or shower if that is not safe for them."]],
  ["h912", 2, ["shampoo", "chanpou"], ["W ap lave tèt yon kliyan nan kabann. Kisa pou w fè?", "Kite cheve a seche nan lè a pandan inèdtan", "Vide dlo sou figi l pou rense pi vit", "Kouvri je l ak yon ti sèvyèt epi seche cheve a vit", "Sèvi ak dlo ki pi cho a pou cheve a pwòp", "Kouvri je kliyan an ak yon ti sèvyèt, epi seche cheve a vit pou l pa frèt."], ["You are washing a client's hair in bed. What should you do?", "Let the hair air-dry for an hour", "Pour water over the face to rinse faster", "Cover their eyes with a small towel and dry the hair promptly", "Use the hottest water so the hair gets clean", "Cover the client's eyes with a small towel, and dry the hair promptly so they do not get chilled."]],
  ["h913", 0, ["toenail care", "swen zong pye"], ["Kliyan an mande w koupe zong pye l. Plan swen an pa pale de sa. Kisa ou fè?", "Pa koupe yo; di enfimyè a", "Koupe yo ak atansyon", "Koupe yo sèlman si yo sanble long", "Mande yon moun nan fanmi an kenbe pye a pandan w ap koupe", "Pa koupe zong pye si plan swen an pa mande l epi w pa fòme pou sa."], ["The client asks you to cut their toenails. The care plan does not mention it. What do you do?", "Do not cut them; tell the nurse", "Cut them carefully", "Cut them only if they look long", "Ask a family member to hold the foot while you cut", "Do not cut toenails unless the care plan calls for it and you are trained."]],
  ["h914", 3, ["denture cup", "bwat dan atifisyèl"], ["Ki kote pou w sere dan atifisyèl kliyan an lè yo pa nan bouch li?", "Vlope nan yon sèvyèt papye sou plato a", "Sèk, nan yon pòch", "Nan yon vè dlo cho", "Nan yon bwat ki gen non kliyan an, ak dlo oswa likid tranpe", "Sere dan atifisyèl nan yon bwat ki gen non kliyan an, ak dlo oswa likid tranpe."], ["Where should the client's dentures be kept when they are out of the mouth?", "Wrapped in a napkin on the tray", "Dry, in a pocket", "In a glass of hot water", "In a container labeled with the client's name, in water or soaking solution", "Store dentures in a container labeled with the client's name, in water or soaking solution."]],
  ["h915", 1, ["dressing", "abiye"], ["Kliyan an gen bò dwat li ki fèb apre yon atak serebral. W ap ede l mete chemiz li. Ki bra ou mete nan manch lan an premye?", "Bra gòch la, bò ki fò a", "Bra dwat la, bò ki fèb la", "Nenpòt, depi l alèz", "Kite l mete chemiz la poukont li", "Abiye bò ki fèb la an premye: bra ki fèb la bezwen plis espas pou l antre nan manch lan. Pou dezabiye, kòmanse ak bò ki fò a."], ["After a stroke, the client's right side is weak. You are helping him put on a shirt. Which arm goes into a sleeve first?", "The left arm, the strong side", "The right arm, the weak side", "Either one, as long as he is comfortable", "Let him put the shirt on by himself", "Dress the weak (affected) side first: the weak arm needs the most room to get into the sleeve. To undress, start with the strong side."]]]
},
{ch:10, cfr:"(b)(3)(x)", observed:true,
 title:["Transfè ak mache an sekirite","Safe transfer and ambulation"],
 src:["S6","S12","S1"],
 sections:[
  {h:["Sa règ la mande","What the rule requires"],src:["S6","S12"],b:[
   ["p","Enfimyè a dwe gade w transfere yon kliyan (egzanp: kabann rive nan chèz) epi ede l mache an sekirite, ak oswa san aparèy (bekiy, mache, chèz woulant).","The nurse must watch you transfer a client (for example, bed to chair) and help them walk safely, with or without devices (cane, walker, wheelchair)."]]},
  {h:["Bon mekanik kò","Good body mechanics"],src:["S1"],b:[
   ["li","Pye w louvri nan lajè zepòl ou pou w gen bon baz.","Feet shoulder-width apart for a wide base."],
   ["li","Pliye jenou w, pa do w. Kenbe do w dwat.","Bend your knees, not your back. Keep your back straight."],
   ["li","Kenbe kliyan an oswa bagay la toupre kò w.","Keep the client or object close to your body."],
   ["li","Vire tout kò w ak pye w; pa tòde do w.","Turn your whole body with your feet; do not twist your back."],
   ["li","Mande èd si kliyan an twò lou oswa plan swen an mande de moun.","Ask for help if the client is too heavy or the care plan calls for two people."]]},
  {h:["Senti mache ak chèz woulant","Gait belt and wheelchair"],src:["S1"],b:[
   ["li","Mete senti mache a sou rad la, nan ren, epi sere l pou w ka glise de dwèt anba l.","Put the gait belt on over clothing at the waist, snug enough to slide two fingers under it."],
   ["li","Pa mete l sou yon blesi, yon tib oswa yon vant ki fèk opere si plan swen an pa pèmèt sa.","Do not put it over a wound, a tube or a recent abdominal surgery unless the care plan allows it."],
   ["li","Bloke fren chèz woulant lan anvan chak transfè, epi leve repoze pye yo.","Lock the wheelchair brakes before every transfer, and lift the footrests out of the way."],
   ["li","Mete chèz la sou bò ki fò a, an ang ak kabann nan.","Place the chair on the client's strong side, angled to the bed."]]},
  {h:["Mache ak yon aparèy","Walking with a device"],src:["S1"],b:[
   ["li","Bekiy (cane): kliyan an kenbe l nan men bò ki fò a. Bekiy la avanse ansanm ak janm ki fèb la.","Cane: the client holds it in the hand on the strong side. The cane moves forward with the weak leg."],
   ["li","Mache (walker): avanse mache a, apre sa janm ki fèb la, apre sa janm ki fò a. Pa leve l twò lwen devan.","Walker: move the walker forward, then the weak leg, then the strong leg. Do not push it too far ahead."],
   ["li","Kanpe bò ki fèb la, yon ti jan dèyè kliyan an, epi kenbe senti mache a.","Stand on the weak side, slightly behind the client, holding the gait belt."],
   ["li","Soulye ki pa glise, chemen ki pwòp, epi pa prese.","Non-skid shoes, a clear path, and no rushing."]]},
  {h:["Toudi ak tonbe","Dizziness and falls"],src:["S1"],b:[
   ["li","Fè kliyan an chita sou kwen kabann nan kèk minit anvan l kanpe: tansyon ka desann lè l leve vit.","Have the client sit on the edge of the bed for a few minutes before standing: blood pressure can drop when rising quickly."],
   ["li","Si l di l toudi, fè l chita ankò epi rapòte l.","If they say they are dizzy, have them sit back down and report it."],
   ["li","Si l kòmanse tonbe pandan l ap mache: pa eseye kenbe l kanpe. Rale l sou ou ak senti mache a, epi desann li dousman atè, pwoteje tèt li.","If they start to fall while walking: do not try to hold them up. Pull them toward you with the gait belt and ease them gently to the floor, protecting the head."],
   ["li","Apre yon tonbe, pa leve l poukont ou. Rele enfimyè a oswa ajans ou, epi rapòte.","After a fall, do not lift them alone. Call the nurse or agency, and report it."]]}],
 terms:[["body mechanics","mekanik kò"],["gait belt","senti mache"],["transfer","transfè"],["ambulation","mache"],["walker","mache (walker)"],["cane","bekiy"],["wheelchair","chèz woulant"],["strong side / weak side","bò ki fò / bò ki fèb"]],
 skills:[
  {title:["Transfè kabann rive nan chèz","Bed-to-chair transfer"],steps:[
   ["Swiv plan swen an. Eksplike kliyan an sa n pral fè.","Follow the care plan. Explain the move to the client."],
   ["Mete chèz la sou bò ki fò a, an ang, epi bloke wou yo.","Place the chair on the strong side at an angle and lock the wheels."],
   ["Fè kliyan an chita sou kwen kabann nan, pye l atè, epi tann kèk minit.","Have the client sit on the edge of the bed, feet flat on the floor, and wait a few minutes."],
   ["Mete soulye ki pa glise pou kliyan an, ak yon senti mache (gait belt).","Put non-skid shoes on the client and apply a gait belt."],
   ["Konte 1-2-3 ansanm, kliyan an kanpe, epi nou vire tou dousman.","Count 1-2-3 together, the client stands, and you pivot slowly."],
   ["Desann kliyan an dousman nan chèz la.","Lower the client gently into the chair."]],
   note:["Pliye jenou w, kenbe do w dwat. Pa janm leve kliyan an pa bra l.","Bend your knees and keep your back straight. Never lift a client by the arms."]},
  {title:["Mache ak yon walker ak senti mache","Walking with a walker and gait belt"],steps:[
   ["Tcheke plan swen an, mete soulye ki pa glise, epi mete senti mache a.","Check the care plan, put on non-skid shoes, and apply the gait belt."],
   ["Fè kliyan an chita sou kwen kabann nan, epi mande l si l toudi.","Have the client sit on the edge of the bed, and ask if they feel dizzy."],
   ["Ede l kanpe; li kenbe de manch walker a.","Help them stand; they hold both walker handles."],
   ["Kanpe bò ki fèb la, yon ti jan dèyè, men w sou senti a.","Stand on the weak side, slightly behind, hand on the belt."],
   ["Walker a avanse, apre sa janm ki fèb la, apre sa janm ki fò a.","Walker forward, then the weak leg, then the strong leg."],
   ["Fini chita nan yon chèz, epi ekri distans lan ak kijan l te mache.","Finish seated in a chair, and record the distance and how they walked."]],
   note:["Si l kòmanse tonbe, desann li dousman atè ak senti a; pa eseye kenbe l kanpe.","If they start to fall, ease them to the floor with the belt; do not try to hold them up."]},
  {title:["Sekirite chèz woulant","Wheelchair safety"],steps:[
   ["Bloke fren yo anvan kliyan an antre oswa soti.","Lock the brakes before the client gets in or out."],
   ["Leve oswa retire repoze pye yo pandan transfè a.","Raise or swing away the footrests during the transfer."],
   ["Lè l chita, mete pye l sou repoze pye yo.","Once seated, place the feet on the footrests."],
   ["Pouse chèz la pa devan; desann yon ranp oswa antre nan yon asansè pa dèyè.","Push forward; go down a ramp or into an elevator backward."],
   ["Tcheke pozisyon an epi bloke fren yo chak fwa w kanpe.","Check positioning and lock the brakes every time you stop."]],
   note:["Kenbe men kliyan an sou kuis li pou yo pa pran nan wou yo.","Keep the client's hands in the lap so they do not catch in the wheels."]}],
 qs:[
  ["h1001",0,["wheelchair brakes","fren chèz woulant"],
   ["Kisa pou w fè anvan w transfere yon kliyan nan yon chèz woulant?","Bloke fren yo epi leve repoze pye yo","Kite chèz la lib pou l fasil pou deplase","Mete chèz la sou bò ki fèb la","Mande kliyan an sote nan chèz la","Bloke fren yo pou chèz la pa glise, epi leve repoze pye yo pou kliyan an pa frape yo."],
   ["What do you do before transferring a client into a wheelchair?","Lock the brakes and raise the footrests","Leave it unlocked so it moves easily","Put the chair on the weak side","Ask the client to jump into the chair","Lock the brakes so the chair does not roll, and move the footrests so the client does not trip on them."]],
  ["h1002",1,["walker","walker"],
   ["Ki lòd kòrèk pou mache ak yon walker?","Janm ki fò a, walker a, janm ki fèb la","Walker a, janm ki fèb la, janm ki fò a","De janm yo anvan, apre sa walker a","Leve walker a twò lwen devan, epi kouri rive","Avanse walker a an premye, apre sa janm ki fèb la, apre sa janm ki fò a."],
   ["What is the correct order for walking with a walker?","Strong leg, walker, weak leg","Walker, weak leg, strong leg","Both legs first, then the walker","Lift the walker far ahead, then hurry to it","Move the walker first, then the weak leg, then the strong leg."]],
  ["h1003",2,["guarding","pwoteje"],
   ["W ap ede yon kliyan mache. Ki kote pou w kanpe?","Devan l, k ap rale l","Bò ki fò a","Bò ki fèb la, yon ti jan dèyè l, men w sou senti mache a","Lwen l pou l gen espas","Kanpe bò ki fèb la, yon ti jan dèyè, pou w ka pwoteje l si l pèdi balans."],
   ["You are helping a client walk. Where do you stand?","In front, pulling them","On the strong side","On the weak side, slightly behind, holding the gait belt","Far away to give space","Stand on the weak side, slightly behind, so you can protect them if they lose balance."]],
  ["h1004",0,["dizziness","toudi"],
   ["Kliyan an di l toudi lè l fin chita sou kwen kabann nan. Kisa ou fè?","Kite l chita oswa kouche ankò epi rapòte l","Fè l kanpe vit pou sa pase","Fè l mache pi vit","Ba l kafe","Toudi lè moun leve ka montre tansyon desann. Pa fè l kanpe: kite l repoze epi rapòte."],
   ["The client says they are dizzy after sitting on the edge of the bed. What do you do?","Let them sit or lie back down and report it","Have them stand quickly so it passes","Have them walk faster","Give them coffee","Dizziness on rising can mean a drop in blood pressure. Do not stand them up: let them rest and report it."]],
  ["h1005",3,["body mechanics","mekanik kò"],
   ["Ki bon mekanik kò lè w ap ede yon kliyan?","Pliye do w epi kenbe jenou w dwat","Tòde do w pou w vire","Kenbe kliyan an lwen kò w","Pye w louvri, jenou pliye, do dwat, epi kliyan an toupre w","Yon baz lajè, jenou pliye ak do dwat pwoteje do w. Vire ak pye w, pa ak do w."],
   ["What is good body mechanics when helping a client?","Bend your back and keep your knees straight","Twist your back to turn","Hold the client far from your body","Feet apart, knees bent, back straight, and the client close to you","A wide base, bent knees and a straight back protect your back. Turn with your feet, not your back."]],
  ["h1006",1,["falling client","kliyan k ap tonbe"],
   ["Kliyan an kòmanse tonbe pandan l ap mache. Kisa ou fè?","Kenbe l kanpe kèlkeswa sa k rive","Rale l sou ou ak senti a epi desann li dousman atè","Lage l pou w pa blese","Rele fanmi an anvan","Pa eseye kenbe yon moun k ap tonbe kanpe: nou de ka blese. Desann li dousman atè, pwoteje tèt li, epi rapòte."],
   ["The client starts to fall while walking. What do you do?","Hold them up no matter what","Pull them toward you with the belt and ease them to the floor","Let go to avoid getting hurt","Call the family first","Do not try to hold a falling person up: you could both be hurt. Ease them to the floor, protect the head, and report it."]],
  ["h1007",2,["gait belt","senti mache"],
   ["Kijan senti mache a dwe sere?","Tèlman sere li fè mak","Lach nèt","Ase pou w ka glise de dwèt anba l","Sou kou kliyan an","Senti a dwe sou rad la, nan ren, sere ase pou w glise de dwèt anba l."],
   ["How snug should the gait belt be?","So tight it leaves marks","Completely loose","Snug enough to slide two fingers under it","Around the client's neck","The belt goes over clothing at the waist, snug enough to slide two fingers under it."]],
  ["hha11",1,["cane","bekiy"],
   ["Kliyan an gen yon janm gòch ki fèb. Nan ki men li dwe kenbe bekiy li?","Men gòch","Men dwat","Nenpòt men","De men yo","Kenbe bekiy la nan men ki opoze ak janm ki fèb la. Li avanse ansanm ak janm ki fèb la pou bay plis sipò."],
   ["The client has a weak left leg. Which hand should hold the cane?","Left hand","Right hand","Either hand","Both hands","Hold the cane in the hand opposite the weak leg. It moves forward with the weak leg to give more support."]],
  ["h1008", 3, ["strong side", "bò ki fò"], ["Apre yon estwòk, bò dwat kliyan an fèb. Ki kote pou w mete chèz woulant lan pou yon transfè kabann rive nan chèz?", "Bò dwat, bò ki fèb la", "Nan pye kabann nan", "Nenpòt bò, si fren yo lage", "Bò gòch, bò ki fò a, ak fren yo bloke", "Mete chèz la sou bò ki fò a pou kliyan an ka sipòte tèt li ak bò sa a pandan l vire. Toujou bloke fren yo."], ["After a stroke, the client's right side is weak. Where do you place the wheelchair for a bed-to-chair transfer?", "On the right, the weak side", "At the foot of the bed", "Either side, with the brakes off", "On the left, the strong side, with the brakes locked", "Place the chair on the strong side so the client can support themselves with it while pivoting. Always lock the brakes."]],
  ["h1009", 2, ["twisting", "tòde do"], ["W ap ede yon kliyan pase depi kabann nan rive sou yon chèz bò kote l. Kijan pou w vire?", "Tòde ren w pandan w ap leve", "Bese ak janm ou dwat", "Vire tout kò w nan deplase pye w", "Kenbe kliyan an lwen ou epi balanse l", "Vire tout kò w ak pye w; pa tòde do w. Kenbe kliyan an toupre w."], ["You are helping a client move from the bed to a chair beside it. How do you turn?", "Twist at the waist while lifting", "Bend over with straight legs", "Turn your whole body by moving your feet", "Hold the client at arm's length and swing them", "Turn your whole body with your feet; do not twist your back. Keep the client close."]],
  ["h1010", 0, ["two-person transfer", "transfè ak de moun"], ["Plan swen an di transfè a bezwen de moun, men ou poukont ou jodi a. Kisa ou fè?", "Pa fè l poukont ou; mande ajans ou èd", "Fè l poukont ou ak anpil atansyon", "Mande kliyan an kanpe poukont li", "Sote transfè a epi pa rapòte l", "Mande èd si kliyan an twò lou oswa plan swen an mande de moun."], ["The care plan says a transfer needs two people, but you are alone today. What do you do?", "Do not do it alone; ask your agency for help", "Do it alone, very carefully", "Ask the client to stand up on their own", "Skip the transfer and do not report it", "Ask for help if the client is too heavy or the care plan calls for two people."]],
  ["h1011", 1, ["gait belt", "senti mache"], ["Kliyan w lan gen yon tib manje nan vant li. Ki kote senti mache a ka ale?", "Dirèk sou tib la, byen sere", "Pa sou tib la si plan swen an pa pèmèt sa; swiv plan an", "Otou pwatrin li", "Anba rad la, sou po a", "Mete senti mache a sou rad la, nan ren. Pa mete l sou yon blesi, yon tib oswa yon vant ki fèk opere si plan swen an pa pèmèt sa."], ["Your client has a feeding tube in the abdomen. Where can the gait belt go?", "Right over the tube, tightly", "Not over the tube unless the care plan allows it; follow the plan", "Around the chest", "Under the clothing, against the skin", "Put the gait belt on over clothing at the waist. Do not put it over a wound, a tube or a recent abdominal surgery unless the care plan allows it."]],
  ["h1012", 3, ["cane", "bekiy"], ["Lè w ap mache ak yon bekiy, kilè bekiy la avanse?", "Anvan janm ki fò a, poukont li", "Sèlman nan eskalye", "Apre de janm yo", "Ansanm ak janm ki fèb la", "Kliyan an kenbe bekiy la bò ki fò a, epi bekiy la avanse ansanm ak janm ki fèb la."], ["When walking with a cane, when does the cane move forward?", "Before the strong leg, on its own", "Only on stairs", "After both legs", "Together with the weak leg", "The client holds the cane on the strong side, and the cane moves forward with the weak leg."]],
  ["h1013", 0, ["dangling", "chita sou kwen kabann"], ["Poukisa kliyan an dwe chita sou kwen kabann nan kèk minit anvan l kanpe?", "Tansyon l ka desann lè l leve vit", "Pou kabann nan chofe", "Pou w gen tan ranje kabann nan", "Pou l ka dòmi pi byen pita", "Chita anvan kite kò a adapte l. Tansyon ka desann lè moun nan leve vit, epi sa ka fè l toudi."], ["Why should the client sit on the edge of the bed for a few minutes before standing?", "Blood pressure can drop when they get up quickly", "It warms up the bed", "It gives you time to make the bed", "It helps them sleep better later", "Sitting first lets the body adjust. Blood pressure can drop when rising quickly, which can cause dizziness."]]]
},
{ch:11, cfr:"(b)(3)(xi)", observed:true,
 title:["Ranje mouvman ak pozisyon","Range of motion and positioning"],
 src:["S6","S12","S1"],
 sections:[
  {h:["Sa règ la mande","What the rule requires"],src:["S6","S12"],b:[
   ["p","Enfimyè a dwe gade w fè egzèsis ranje mouvman (range of motion, ROM) ak chanje pozisyon kliyan an. Swiv sèlman egzèsis ki nan plan swen an, jan terapis la oswa enfimyè a ekri yo.","The nurse must watch you do range-of-motion (ROM) exercises and reposition a client. Do only the exercises in the care plan, as the therapist or nurse wrote them."]]},
  {h:["Pasif oswa aktif","Passive or active"],src:["S1"],b:[
   ["li","Aktif: kliyan an fè mouvman an poukont li.","Active: the client moves the joint on their own."],
   ["li","Aktif ak èd: kliyan an fè yon pati, ou ede l fini.","Active-assisted: the client does part of it and you help finish."],
   ["li","Pasif: ou fè mouvman an pou kliyan an ki pa ka fè l.","Passive: you move the joint for a client who cannot."]]},
  {h:["Règ pou ROM","Rules for ROM"],src:["S1"],b:[
   ["li","Sipòte jwenti a: yon men anwo, yon men anba li.","Support the joint: one hand above it, one hand below it."],
   ["li","Fè mouvman yo dousman, regilye, epi menm kantite fwa jan plan an di.","Move slowly and smoothly, the number of times the plan says."],
   ["li","Pa janm fòse yon jwenti pi lwen pase kote l rive fasil.","Never force a joint past where it moves easily."],
   ["li","Rete si kliyan an gen doulè, epi rapòte l.","Stop if the client has pain, and report it."],
   ["li","Pa fè ROM sou kou oswa sou yon jwenti ki fèk opere, si plan swen an pa mande l.","Do not do ROM on the neck or a recently operated joint unless the care plan calls for it."]]},
  {h:["Pozisyon ak chanje pozisyon","Positioning and repositioning"],src:["S1"],b:[
   ["li","Yon kliyan ki pa ka deplase poukont li bezwen chanje pozisyon omwen chak 2 èdtan, oswa jan plan swen an di.","A client who cannot move on their own needs repositioning at least every 2 hours, or as the care plan says."],
   ["li","Sou kote: yon zòrye ant jenou yo ak dèyè do a.","Side-lying: a pillow between the knees and one behind the back."],
   ["li","Leve talon yo (float heels) ak yon zòrye anba mollèt yo pou talon yo pa peze kabann nan.","Float the heels with a pillow under the calves so the heels do not press on the bed."],
   ["li","Fowler: tèt kabann nan leve (anviwon 45 a 60 degre), bon pou manje ak respire.","Fowler's: head of the bed raised (about 45 to 60 degrees), good for eating and breathing."],
   ["li","Pa rale kliyan an sou dra yo: sa ka chire po a. Sèvi ak yon dra pou leve (draw sheet) ak yon lòt moun.","Do not drag the client across the sheets: it can tear the skin. Use a draw sheet and a second person."]]}],
 terms:[["range of motion (ROM)","ranje mouvman"],["passive","pasif"],["active","aktif"],["joint","jwenti"],["reposition","chanje pozisyon"],["Fowler's position","pozisyon Fowler"],["float the heels","leve talon yo"],["draw sheet","dra pou leve"]],
 skills:[
  {title:["ROM pasif: zepòl","Passive ROM: shoulder"],steps:[
   ["Lave men w, eksplike, epi kouche kliyan an sou do.","Clean your hands, explain, and lay the client on their back."],
   ["Sipòte koud la ak ponyèt la.","Support the elbow and the wrist."],
   ["Leve bra a dousman devan, rive anlè tèt la, epi desann li (flexion/extension).","Raise the arm slowly forward, up over the head, and back down (flexion/extension)."],
   ["Deplase bra a sou kote, lwen kò a, epi tounen (abduction/adduction).","Move the arm out to the side, away from the body, and back (abduction/adduction)."],
   ["Fè chak mouvman kantite fwa plan swen an di; rete si gen doulè.","Repeat each move as many times as the care plan says; stop if there is pain."],
   ["Ekri sa w fè ak kijan kliyan an reyaji.","Record what you did and how the client responded."]],
   note:["Pa janm fòse jwenti a.","Never force the joint."]},
  {title:["ROM pasif: ranch ak jenou","Passive ROM: hip and knee"],steps:[
   ["Kliyan an sou do. Sipòte anba jenou an ak talon an.","Client on their back. Support under the knee and the heel."],
   ["Pliye jenou an epi pote l vè pwatrin nan dousman, epi lonje l ankò.","Bend the knee and bring it gently toward the chest, then straighten it."],
   ["Ak janm nan dwat, deplase l sou kote, lwen lòt janm nan, epi tounen.","With the leg straight, move it out to the side, away from the other leg, and back."],
   ["Fè kantite fwa plan an di; rete si gen doulè.","Repeat as the plan says; stop if there is pain."],
   ["Kouvri kliyan an epi ekri sa w fè.","Cover the client and record what you did."]],
   note:["Rapòte doulè, rèd oswa anflamasyon ki fèk parèt.","Report new pain, stiffness or swelling."]},
  {title:["Vire kliyan an sou kote","Turning the client onto the side"],steps:[
   ["Eksplike, bay prive, epi bloke wou kabann nan si l genyen.","Explain, give privacy, and lock the bed wheels if it has them."],
   ["Kanpe sou bò kote kliyan an pral vire a. Kwaze bra l sou pwatrin li epi kwaze janm ki lwen an sou lòt la.","Stand on the side the client will turn toward. Cross their arms over the chest and the far leg over the near one."],
   ["Mete men w sou zepòl ak ranch ki lwen an, epi vire l dousman vè ou.","Place your hands on the far shoulder and hip, and roll them gently toward you."],
   ["Mete yon zòrye dèyè do a ak yon lòt ant jenou yo.","Place a pillow behind the back and another between the knees."],
   ["Tcheke ke zòrèy, zepòl ak talon yo pa peze, epi kite sonèt la nan rive men l.","Check that the ears, shoulder and heels are not under pressure, and leave the call bell within reach."]],
   note:["Ekri lè w chanje pozisyon an; swiv orè plan swen an.","Record the time you repositioned; follow the care plan's schedule."]}],
 qs:[
  ["h1101",0,["passive ROM","ROM pasif"],
   ["Kisa ROM pasif ye?","Ou fè mouvman jwenti a pou kliyan an ki pa ka fè l","Kliyan an fè egzèsis la poukont li","Kliyan an mache nan kay la","Yon egzèsis ak pwa lou","Nan ROM pasif, ou deplase jwenti a pou kliyan an. Nan ROM aktif, kliyan an fè l poukont li."],
   ["What is passive range of motion?","You move the joint for a client who cannot","The client exercises on their own","The client walks around the house","An exercise with heavy weights","In passive ROM, you move the joint for the client. In active ROM, the client does it on their own."]],
  ["h1102",2,["pain","doulè"],
   ["Pandan ROM, kliyan an di l gen doulè. Kisa ou fè?","Kontinye pou jwenti a vin pi soup","Fòse l yon ti kras plis","Rete epi rapòte l bay enfimyè a","Ba l yon grenn pou doulè","Pa janm fòse yon jwenti. Rete lè gen doulè epi rapòte l."],
   ["During ROM, the client says it hurts. What do you do?","Keep going to loosen the joint","Push it a little further","Stop and report it to the nurse","Give a pain pill","Never force a joint. Stop when there is pain and report it."]],
  ["h1103",1,["support the joint","sipòte jwenti a"],
   ["Kijan pou w kenbe yon jwenti pandan ROM?","Pa pwent dwèt yo sèlman","Yon men anwo jwenti a, yon men anba l","Pa rad kliyan an","Ou pa bezwen kenbe l","Sipòte jwenti a ak yon men anwo epi yon men anba pou mouvman an rete lis epi an sekirite."],
   ["How should you hold a joint during ROM?","By the fingertips only","One hand above the joint and one below it","By the client's clothing","You do not need to hold it","Support the joint with one hand above and one below so the movement stays smooth and safe."]],
  ["h1104",3,["reposition","chanje pozisyon"],
   ["Konbyen fwa yon kliyan ki pa ka deplase dwe chanje pozisyon?","Yon fwa pa jou","Sèlman lè l mande","Chak 8 èdtan","Omwen chak 2 èdtan, oswa jan plan swen an di","Chanje pozisyon souvan, omwen chak 2 èdtan, diminye presyon sou po a epi anpeche blesi presyon."],
   ["How often should a client who cannot move be repositioned?","Once a day","Only when they ask","Every 8 hours","At least every 2 hours, or as the care plan says","Repositioning at least every 2 hours relieves pressure on the skin and helps prevent pressure injuries."]],
  ["h1105",0,["float the heels","leve talon yo"],
   ["Kijan pou w pwoteje talon yon kliyan ki rete kouche?","Mete yon zòrye anba mollèt yo pou talon yo pa touche kabann nan","Mete zòrye dirèk anba talon yo","Fwote talon yo fò","Mete chosèt sere","Leve talon yo ak yon zòrye anba mollèt yo pou yo pa peze kabann nan."],
   ["How do you protect the heels of a client who stays in bed?","Put a pillow under the calves so the heels do not touch the bed","Put a pillow directly under the heels","Rub the heels hard","Put on tight socks","Float the heels with a pillow under the calves so they do not press on the bed."]],
  ["h1106",2,["side-lying","sou kote"],
   ["Lè kliyan an kouche sou kote, ki kote pou w mete yon zòrye?","Anba tèt li sèlman","Sou vant li","Ant jenou yo ak dèyè do a","Pa gen zòrye","Yon zòrye ant jenou yo anpeche zo yo peze youn sou lòt, epi youn dèyè do a kenbe pozisyon an."],
   ["When the client lies on their side, where do you place a pillow?","Under the head only","On the stomach","Between the knees and behind the back","No pillows","A pillow between the knees keeps the bones from pressing together, and one behind the back holds the position."]],
  ["h1107",1,["Fowler's","Fowler"],
   ["Ki pozisyon ki bon pou yon kliyan manje oswa respire pi byen nan kabann?","Plat sou do","Fowler, tèt kabann nan leve","Sou vant","Tèt pi ba pase pye","Pozisyon Fowler, ak tèt kabann nan leve, ede kliyan an manje an sekirite epi respire pi fasil."],
   ["Which position helps a client eat or breathe better in bed?","Flat on the back","Fowler's, with the head of the bed raised","On the stomach","Head lower than feet","Fowler's position, with the head of the bed raised, helps the client eat safely and breathe more easily."]],
  ["h1108",3,["draw sheet","dra pou leve"],
   ["W ap monte yon kliyan pi wo nan kabann nan. Kijan pou w fè l?","Rale l pa bra l","Rale l sou dra a poukont ou","Pouse l pa pye l","Sèvi ak yon dra pou leve (draw sheet) ak yon lòt moun","Rale kliyan an sou dra yo ka chire po a. Sèvi ak yon dra pou leve ak yon lòt moun, epi pa janm rale pa bra yo."],
   ["You are moving a client up in bed. How should you do it?","Pull them by the arms","Drag them on the sheet alone","Push them by the feet","Use a draw sheet with a second person","Dragging the client on the sheets can tear the skin. Use a draw sheet with a second person, and never pull by the arms."]],
  ["h1109", 1, ["care plan exercises", "egzèsis plan swen an"], ["Kliyan w lan mande w ajoute kèk nouvo egzèsis li wè nan televizyon. Kisa ou fè?", "Ajoute yo si yo sanble fasil", "Fè sèlman egzèsis ki nan plan swen an, epi di enfimyè a sa l mande", "Ranplase egzèsis plan an ak nouvo yo", "Fè yo de fwa plis pou l refè pi vit", "Swiv sèlman egzèsis ki nan plan swen an, jan terapis la oswa enfimyè a ekri yo. Di enfimyè a sa kliyan an mande."], ["Your client asks you to add some new exercises they saw on TV. What do you do?", "Add them if they look easy", "Do only the exercises in the care plan, and tell the nurse about the request", "Replace the plan's exercises with the new ones", "Do them twice as often to recover faster", "Do only the exercises in the care plan, as the therapist or nurse wrote them. Tell the nurse about the request."]],
  ["h1110", 2, ["active-assisted ROM", "ROM aktif ak èd"], ["Kliyan an leve bra l mwatye chemen epi ou ede l fini mouvman an. Ki kalite ranje mouvman sa a ye?", "Pasif", "Aktif", "Aktif ak èd", "Ak rezistans", "Aktif ak èd vle di kliyan an fè yon pati nan mouvman an epi ou ede l fini l."], ["The client raises their arm halfway and you help them finish the movement. What type of range of motion is this?", "Passive", "Active", "Active-assisted", "Resistive", "Active-assisted means the client does part of the movement and you help finish it."]],
  ["h1111", 3, ["force a joint", "fòse yon jwenti"], ["Pandan ranje mouvman, jenou kliyan an sispann pliye anvan kote l konn rive. Kisa ou fè?", "Pouse yon ti jan pi fò pou rive kote l konn rive", "Souke jwenti a pou l lache", "Mande kliyan an fòse", "Rete la; pa janm fòse yon jwenti pi lwen pase kote l rive fasil", "Fè mouvman yo dousman, epi pa janm fòse yon jwenti pi lwen pase kote l rive fasil. Rete si gen doulè, epi rapòte l."], ["During range of motion, the client's knee stops bending before its usual point. What do you do?", "Push a little harder to reach the usual point", "Bounce the joint to loosen it", "Ask the client to push through it", "Stop there; never force a joint past where it moves easily", "Move slowly and smoothly, and never force a joint past where it moves easily. Stop if there is pain, and report it."]],
  ["h1112", 0, ["recent surgery", "operasyon resan"], ["Kliyan w lan te fè operasyon ranch semèn pase. Plan swen an pa gen ROM pou ranch sa a. Kisa ou fè?", "Pa fè ROM sou ranch sa a", "Fè yon ti ROM dous sou ranch lan kanmenm", "Fè ROM sèlman si kliyan an dakò", "Fè plis ROM pou l pa rèd", "Pa fè ROM sou kou oswa sou yon jwenti ki fèk opere si plan swen an pa mande l."], ["Your client had hip surgery last week. The care plan does not include ROM for that hip. What do you do?", "Do not do ROM on that hip", "Do gentle ROM on the hip anyway", "Do ROM only if the client agrees", "Do extra ROM to prevent stiffness", "Do not do range of motion on the neck or a recently operated joint unless the care plan calls for it."]]]
}
);

/* HHA exam FAQ. Each item: [q HT, q EN, a HT, a EN, sources] */
window.HHA_FAQ = [
 ["Èske gen yon egzamen leta pou HHA?","Is there a state HHA exam?",
  "Pa gen yon sèl egzamen nasyonal. Règ federal la (42 CFR 484.80) mande yon evalyasyon konpetans, men se ajans lan oswa pwogram fòmasyon an ki fè l. Kèk eta gen pwòp règ yo. Nan Massachusetts, nou poko konfime yon règ leta separe: mande ajans oswa lekòl ou.",
  "There is no single national exam. The federal rule (42 CFR 484.80) requires a competency evaluation, but the agency or training program runs it. Some states add their own rules. For Massachusetts, we have not confirmed a separate state rule: ask your agency or school.",["S6","S12"]],
 ["Kisa evalyasyon konpetans lan gen ladan?","What does the competency evaluation include?",
  "De pati: yon tès ekri oswa oral sou 14 sijè yo, ak konpetans pratik yon enfimyè (RN) gade w fè ak yon kliyan oswa yon moun k ap jwe wòl kliyan. Konpetans pratik yo se: kominikasyon, siy vital, ijyèn pèsonèl, transfè ak mache, ak ranje mouvman ak pozisyon.",
  "Two parts: a written or oral test on the 14 subjects, and hands-on skills a registered nurse watches you do with a client or a person playing the client. The hands-on skills are: communication, vital signs, personal hygiene, transfers and walking, and range of motion and positioning.",["S6","S12"]],
 ["Kisa k rive si m echwe yon konpetans?","What happens if I fail a skill?",
  "Ou pa ka fè travay sa a san sipèvizyon dirèk jiskaske w fè fòmasyon ankò epi pase yon nouvo evalyasyon pou li. Si w echwe plis pase yon sijè obligatwa, ou pa konsidere kòm konpetan: ou dwe fè fòmasyon ankò epi pase evalyasyon an ankò.",
  "You may not do that task without direct supervision until you are retrained and pass a new evaluation for it. If you fail more than one required area, you are not considered competent: you must be retrained and evaluated again.",["S6","S12"]],
 ["Konbyen èdtan fòmasyon?","How many training hours?",
  "Omwen 75 èdtan, ak omwen 16 èdtan klas anvan omwen 16 èdtan pratik sipèvize. Pati klas la ka fèt sou entènèt si l entèaktif. Kèk eta mande plis èdtan.",
  "At least 75 hours, with at least 16 hours of classroom before at least 16 hours of supervised practical training. The classroom part can be online if it is interactive. Some states require more hours.",["S6","S12"]],
 ["Konbyen tan sa pran?","How long does it take?",
  "Anpil pwogram 75 èdtan pran kèk semèn (souvan 2 a 3 semèn a plen tan). Sa depann de orè pwogram nan.",
  "Many 75-hour programs take a few weeks (often 2 to 3 weeks full time). It depends on the program's schedule.",["S16"]],
 ["Èske yon CNA ka travay kòm HHA?","Can a CNA work as an HHA?",
  "Wi, dapre règ federal la, yon asistan enfimyè ki sou rejis leta a an règ ka kalifye kòm ed swen a domisil. Ajans lan ka toujou mande w fè yon evalyasyon sou travay lakay moun.",
  "Yes. Under the federal rule, a nurse aide in good standing on the state registry can qualify as a home health aide. The agency may still ask you to show skills for home care.",["S6","S12"]],
 ["Sètifika HHA sou entènèt: èske yo valab?","Online HHA certificates: are they valid?",
  "Fè atansyon. Kèk sit vann pwòp “sètifikasyon” prive pa yo. Pou travay nan yon ajans Medicare, ou bezwen fòmasyon ak evalyasyon ki respekte 42 CFR 484.80, ak yon pati pratik ak yon RN. Mande ajans ou vle travay la ki pwogram li aksepte anvan w peye.",
  "Be careful. Some sites sell their own private “certifications.” To work for a Medicare agency, you need training and an evaluation that meet 42 CFR 484.80, including a hands-on part with an RN. Ask the agency you want to work for which programs it accepts before you pay.",["S6","S16"]],
 ["Kisa m bezwen anvan m kòmanse?","What do I need before I start?",
  "Sa varye selon pwogram ak ajans. Souvan yo mande yon verifikasyon dosye (background check), yon tès TB, ak pafwa vaksen. Mande pwogram oswa ajans lan lis egzak la.",
  "It varies by program and agency. Many ask for a background check, a TB test, and sometimes vaccines. Ask the program or agency for the exact list.",["S16"]],
 ["Kijan pou m rete kalifye?","How do I stay qualified?",
  "Fè omwen 12 èdtan fòmasyon kontinyèl (in-service) chak 12 mwa. Si w pase 24 mwa youn apre lòt san w pa travay pou peye kòm ed, ou dwe fè fòmasyon ak evalyasyon ankò.",
  "Complete at least 12 hours of in-service training every 12 months. If you go 24 months in a row without paid work as an aide, you must complete training and evaluation again.",["S6","S12"]],
 ["Kijan app sa a ede m?","How does this app help?",
  "Li kouvri 14 sijè federal yo, ak gid, kesyon ak kat konpetans pou chak. Li pa ranplase fòmasyon ofisyèl ou ni pratik ak yon enfimyè. Toujou swiv plan swen kliyan an ak règ ajans ou.",
  "It covers all 14 federal subjects, with guides, questions and skill cards for each. It does not replace your official training or hands-on practice with a nurse. Always follow the client's care plan and your agency's rules.",["S6"]]
];
